<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__,2).'/config/config.php';
function academic_dashboard_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())academic_dashboard_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))academic_dashboard_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);if(($_SESSION['role']??'')!=='head_academic')academic_dashboard_json(403,['ok'=>false,'message'=>'This dashboard is for the Head of Academics.']);$uid=(int)$_SESSION['user_id'];$school=filter_var($_GET['school_id']??null,FILTER_VALIDATE_INT);if(!$school)academic_dashboard_json(422,['ok'=>false,'message'=>'Choose a school.']);
try{$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())academic_dashboard_json(403,['ok'=>false,'message'=>'That school is outside your access.']);$counts=[];foreach(['schemes'=>"SELECT COUNT(*) FROM schemes_of_work WHERE school_id=? AND status='submitted'",'lessons'=>"SELECT COUNT(*) FROM lesson_plans WHERE school_id=? AND status='submitted'",'reports'=>"SELECT COUNT(*) FROM teacher_reports WHERE school_id=? AND status='submitted'",'exams'=>"SELECT COUNT(*) FROM school_exams WHERE school_id=? AND status='submitted'"] as $key=>$sql){$q=$db->prepare($sql);$q->execute([$school]);$counts[$key]=(int)$q->fetchColumn();}$q=$db->prepare('SELECT COUNT(*),COALESCE(SUM(tr.periods_delivered),0) FROM teaching_records tr WHERE tr.school_id=? AND tr.taught_on>=DATE_SUB(CURRENT_DATE,INTERVAL 30 DAY)');$q->execute([$school]);$coverage=$q->fetch(PDO::FETCH_NUM);$q=$db->prepare("SELECT x.kind,x.id,x.label,x.owner,x.created_at FROM (SELECT 'Scheme' kind,s.id,CONCAT(c.name,' · ',sub.name,' · ',s.title) label,u.name owner,s.updated_at created_at FROM schemes_of_work s JOIN school_classes c ON c.id=s.class_id JOIN school_class_subjects sub ON sub.id=s.subject_id JOIN users u ON u.id=s.created_by WHERE s.school_id=? AND s.status='submitted' UNION ALL SELECT 'Lesson',l.id,CONCAT(c.name,' · ',sub.name,' · ',l.title),u.name,l.updated_at FROM lesson_plans l JOIN schemes_of_work s ON s.id=l.scheme_id JOIN school_classes c ON c.id=s.class_id JOIN school_class_subjects sub ON sub.id=s.subject_id JOIN users u ON u.id=l.teacher_id WHERE l.school_id=? AND l.status='submitted' UNION ALL SELECT 'Teacher report',r.id,CONCAT(r.report_type,' report · ',r.period_start,' to ',r.period_end),u.name,r.updated_at FROM teacher_reports r JOIN users u ON u.id=r.teacher_id WHERE r.school_id=? AND r.status='submitted' UNION ALL SELECT 'Examination',e.id,CONCAT(e.name,' · ',e.academic_year,' · ',COALESCE(e.term,'')),u.name,e.created_at FROM school_exams e JOIN users u ON u.id=e.created_by WHERE e.school_id=? AND e.status='submitted') x ORDER BY x.created_at LIMIT 12");$q->execute([$school,$school,$school,$school]);academic_dashboard_json(200,['ok'=>true,'data'=>['submitted_schemes'=>$counts['schemes'],'submitted_lessons'=>$counts['lessons'],'submitted_reports'=>$counts['reports'],'exams_for_review'=>$counts['exams'],'confirmed_lessons_30d'=>(int)($coverage[0]??0),'periods_delivered_30d'=>(int)($coverage[1]??0),'review_queue'=>$q->fetchAll()]]);}catch(Throwable $e){error_log('Academic dashboard request failed: '.$e->getMessage());academic_dashboard_json(500,['ok'=>false,'message'=>'Academic dashboard data could not be loaded.']);}
